#include <stdio.h>
#include <stdlib.h>

typedef struct { int start; int end; } Interval;

int cmp(const void *a, const void *b) {
    return ((Interval*)a)->start - ((Interval*)b)->start;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    Interval *invs = malloc(n * sizeof(Interval));
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &invs[i].start, &invs[i].end);
    }
    qsort(invs, n, sizeof(Interval), cmp);
    int cur_start = invs[0].start;
    int cur_end = invs[0].end;
    for (int i = 1; i < n; i++) {
        if (invs[i].start <= cur_end) {
            if (invs[i].end > cur_end) cur_end = invs[i].end;
        } else {
            printf("%d %d\n", cur_start, cur_end);
            cur_start = invs[i].start;
            cur_end = invs[i].end;
        }
    }
    printf("%d %d\n", cur_start, cur_end);
    free(invs);
    return 0;
}
